// Validate and normalize input
const input = $input.first().json.body || $input.first().json;

// Extract parameters with defaults
const topicId = input.topic_id || null;
const topicText = input.topic || null;
const depth = input.depth || 'medium';
const focusAreas = input.focus_areas || [];
const callbackWorkflow = input.callback_workflow || null;

// Validate we have something to research
if (!topicId && !topicText) {
  throw new Error('Must provide either topic_id or topic text');
}

// Validate depth
const validDepths = ['light', 'medium', 'deep'];
if (!validDepths.includes(depth)) {
  throw new Error(`Invalid depth: ${depth}. Must be: ${validDepths.join(', ')}`);
}

// Determine query count based on depth
const queryConfig = {
  light: { count: 3, description: 'Quick overview' },
  medium: { count: 7, description: 'Comprehensive research' },
  deep: { count: 15, description: 'Exhaustive deep-dive' }
};

return [{
  json: {
    topic_id: topicId,
    topic: topicText,
    depth: depth,
    query_count: queryConfig[depth].count,
    depth_description: queryConfig[depth].description,
    focus_areas: focusAreas,
    callback_workflow: callbackWorkflow,
    started_at: new Date().toISOString()
  }
}];

// Merge Airtable data with original request
const original = $('Validate Input').first().json;
const airtableData = $input.first().json;

return [{
  json: {
    ...original,
    topic: airtableData.Topic || airtableData.fields?.Topic || original.topic,
    topic_id: airtableData.id || original.topic_id,
    // Preserve any additional metadata from Airtable
    niche: airtableData.Niche || airtableData.fields?.Niche || null,
    existing_score: airtableData.Score || airtableData.fields?.Score || null
  }
}];

// Pass through with topic text only
const original = $('Validate Input').first().json;

return [{
  json: {
    ...original,
    topic: original.topic,
    topic_id: null  // Will be created after research
  }
}];

// Generate research queries based on depth and focus areas
const input = $input.first().json;
const topic = input.topic;
const depth = input.depth;
const focusAreas = input.focus_areas || [];

// Base query templates by depth
const queryTemplates = {
  light: [
    `${topic} key facts and statistics 2024`,
    `${topic} common mistakes to avoid`,
    `${topic} quick actionable tips`
  ],
  medium: [
    `${topic} key facts and statistics 2024`,
    `${topic} common mistakes to avoid`,
    `${topic} quick actionable tips`,
    `${topic} expert opinions and insights`,
    `${topic} real world case studies examples`,
    `${topic} research studies data`,
    `${topic} best practices comprehensive guide`
  ],
  deep: [
    `${topic} key facts and statistics 2024`,
    `${topic} common mistakes to avoid`,
    `${topic} quick actionable tips`,
    `${topic} expert opinions and insights`,
    `${topic} real world case studies examples`,
    `${topic} research studies data`,
    `${topic} best practices comprehensive guide`,
    `${topic} scientific research academic papers`,
    `${topic} industry reports market analysis`,
    `${topic} historical evolution timeline`,
    `${topic} future predictions trends experts`,
    `${topic} controversial debates different perspectives`,
    `${topic} success stories and failures lessons learned`,
    `${topic} tools software comparison reviews`,
    `${topic} certification training programs courses`
  ]
};

// Get queries for selected depth
let queries = queryTemplates[depth] || queryTemplates.medium;

// Add focus area queries if provided
if (focusAreas.length > 0) {
  focusAreas.forEach(area => {
    queries.push(`${topic} ${area} detailed guide`);
  });
}

// Tag each query with its purpose for later synthesis
const taggedQueries = queries.map((query, index) => {
  let category = 'general';
  if (query.includes('statistics') || query.includes('data')) category = 'statistics';
  else if (query.includes('expert') || query.includes('opinions')) category = 'expert';
  else if (query.includes('case stud') || query.includes('example')) category = 'examples';
  else if (query.includes('mistake') || query.includes('avoid')) category = 'warnings';
  else if (query.includes('tips') || query.includes('actionable')) category = 'actionable';
  else if (query.includes('research') || query.includes('academic')) category = 'academic';
  else if (query.includes('prediction') || query.includes('future')) category = 'trends';

  return {
    query: query,
    index: index,
    category: category
  };
});

// Return each query as separate item for batch processing
return taggedQueries.map(q => ({
  json: {
    ...input,
    current_query: q.query,
    query_index: q.index,
    query_category: q.category,
    total_queries: taggedQueries.length
  }
}));

