// Parse and validate synthesized research
const input = $input.first().json;
const collectedData = $('Collect All Responses').first().json.data;
const metadata = collectedData[0]; // Get metadata from first item

// Parse GPT response
let research = {};
try {
  const content = input.message?.content || input.content || '{}';
  research = typeof content === 'string' ? JSON.parse(content) : content;
} catch (e) {
  console.error('Failed to parse research JSON:', e);
  research = {
    summary: 'Failed to synthesize research',
    insights: [],
    quotes: [],
    statistics: [],
    sources: [],
    key_themes: []
  };
}

// Ensure all arrays exist
research.insights = research.insights || [];
research.quotes = research.quotes || [];
research.statistics = research.statistics || [];
research.sources = research.sources || [];
research.key_themes = research.key_themes || [];

// Calculate quality metrics
const qualityScore = Math.min(100, 
  (research.insights.length * 5) +
  (research.quotes.length * 10) +
  (research.statistics.length * 8) +
  (research.sources.length * 3) +
  (research.summary.length > 200 ? 20 : 10)
);

// Build final research package
const researchPackage = {
  // Metadata
  topic_id: metadata.topic_id,
  topic: metadata.topic,
  depth: metadata.depth,
  callback_workflow: metadata.callback_workflow,

  // Research content
  summary: research.summary,
  insights: JSON.stringify(research.insights),
  quotes: JSON.stringify(research.quotes),
  statistics: JSON.stringify(research.statistics),
  sources: JSON.stringify(research.sources),
  key_themes: JSON.stringify(research.key_themes),

  // Metrics
  quality_score: qualityScore,
  query_count: metadata.total_queries,
  insight_count: research.insights.length,
  quote_count: research.quotes.length,
  stat_count: research.statistics.length,
  source_count: research.sources.length,

  // Timestamps
  started_at: metadata.started_at,
  completed_at: new Date().toISOString()
};

return [{ json: researchPackage }];

