// Build final response
const researchPackage = $('Build Research Package').first().json;
const airtableRecord = $('Save to Airtable').first().json;

const response = {
  success: true,
  research_id: airtableRecord.id,
  topic: researchPackage.topic,
  topic_id: researchPackage.topic_id,
  depth: researchPackage.depth,
  quality_score: researchPackage.quality_score,
  metrics: {
    queries_executed: researchPackage.query_count,
    insights_found: researchPackage.insight_count,
    quotes_found: researchPackage.quote_count,
    statistics_found: researchPackage.stat_count,
    sources_cited: researchPackage.source_count
  },
  timing: {
    started_at: researchPackage.started_at,
    completed_at: researchPackage.completed_at,
    duration_seconds: Math.round(
      (new Date(researchPackage.completed_at) - new Date(researchPackage.started_at)) / 1000
    )
  },
  callback_triggered: !!researchPackage.callback_workflow,
  airtable_url: `https://airtable.com/appXXXXXXXXXXXXXX/tblResearch/${airtableRecord.id}`
};

return [{ json: response }];
